select room_id
from cr_role
where user_ids like #{userId}


select room_id
from cr_role
where business_type = #{code}
and user_ids like #{user_id}


select room_id, role_group
from cr_role
where business_type = #{code}
and user_ids like #{user_id}

select resource_id, `name`, room_id, description, role_group, nodes, user_ids, exercise_paper, parent_resource_id, mission_scheme, business_type from cr_role where room_id = #{roomId}
and (role_group like #{roleId} or resource_id = #{roleId}
or role_group in (1,2,3)
)


select * from cr_role
where room_id = #{roomId}
and mission_scheme like #{mission_id}

select * from cr_role
where room_id = #{roomId}
and role_group in

    #{group}
